    border-radius:1rem;padding:2rem;}
  .funder-card .value{font-family:'Anton',sans-serif;font-size:48px;color:var(--pink);}
  .funder-card .lbl{font-size:13px;color:rgba(255,255,255,0.5);text-transform:uppercase;letter-spacing:0.08em;margin-top:0.25rem;}

